import{_ as e,o as t,c as s,a6 as i}from"./chunks/framework.BBIckNDn.js";const p=JSON.parse('{"title":"学習ロードマップ","description":"","frontmatter":{"title":"学習ロードマップ","study":{"source":"C++ Wiki","kind":"学習ガイド","status":"既存原稿","summary":"自分の目的に合ったルートを選んでください。どのルートも「全部読む」必要はありません。各ページは独立して読めるように書かれており、未説明の用語には用語集やリンク先ページへの参照があります。"}},"headers":[],"relativePath":"guide/cpp-roadmap.md","filePath":"guide/cpp-roadmap.md"}'),n={name:"guide/cpp-roadmap.md"};function l(r,a,d,h,u,o){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="学習ロードマップ" tabindex="-1">学習ロードマップ <a class="header-anchor" href="#学習ロードマップ" aria-label="Permalink to &quot;学習ロードマップ&quot;">​</a></h1><p>自分の目的に合ったルートを選んでください。どのルートも「全部読む」必要はありません。各ページは独立して読めるように書かれており、未説明の用語には<a href="/study/guide/cpp-glossary.html">用語集</a>やリンク先ページへの参照があります。</p><h2 id="ルート0-まず全員に勧める最短コース-約10ページ" tabindex="-1">ルート0: まず全員に勧める最短コース(約10ページ) <a class="header-anchor" href="#ルート0-まず全員に勧める最短コース-約10ページ" aria-label="Permalink to &quot;ルート0: まず全員に勧める最短コース(約10ページ)&quot;">​</a></h2><p>「設計もC++もまだ自信がない」状態から、このWiki全体の見取り図を作るためのコースです。</p><ol><li><a href="/study/design/foundations/what-is-design.html">設計とは何を決める行為なのか</a></li><li><a href="/study/design/foundations/cohesion-and-coupling.html">凝集度と結合度</a></li><li><a href="/study/design/foundations/inheritance-delegation-composition.html">継承・委譲・コンポジション</a></li><li><a href="/study/design/solid/srp.html">SRP: 単一責任の原則</a></li><li><a href="/study/design/patterns/observer.html">Observer</a>(Unityのeventの正体)</li><li><a href="/study/design/patterns/state.html">State</a>(ゲームで最頻出)</li><li><a href="/study/languages/cpp/values-pointers-references.html">値型と参照・ポインタ・参照</a></li><li><a href="/study/languages/cpp/raii.html">RAII</a></li><li><a href="/study/runtime/cpp-internals/build-pipeline-journey.html">main.cpp から CPU命令までの旅</a></li><li><a href="/study/design/case-studies/weapon-switching.html">ケーススタディ: 武器切り替え</a></li></ol><h2 id="ルート1-初心者向け-設計もc-も基礎から" tabindex="-1">ルート1: 初心者向け(設計もC++も基礎から) <a class="header-anchor" href="#ルート1-初心者向け-設計もc-も基礎から" aria-label="Permalink to &quot;ルート1: 初心者向け(設計もC++も基礎から)&quot;">​</a></h2><p>順番に読むと、前のページの知識だけで次が読めるように並べています。</p><ol><li>第1部を順番に: <a href="/study/design/foundations/what-is-design.html">設計とは</a> → <a href="/study/design/foundations/responsibility-and-separation.html">責務</a> → <a href="/study/design/foundations/cohesion-and-coupling.html">凝集度と結合度</a> → <a href="/study/design/foundations/dependency.html">依存</a> → <a href="/study/design/foundations/abstraction-encapsulation.html">抽象化</a> → <a href="/study/design/foundations/inheritance-delegation-composition.html">継承とコンポジション</a> → <a href="/study/design/foundations/polymorphism-interface.html">ポリモーフィズム</a> → <a href="/study/design/foundations/quality-attributes.html">品質特性</a> → <a href="/study/design/foundations/yagni-kiss-dry.html">YAGNI/KISS/DRY</a> → <a href="/study/design/foundations/tech-debt-and-refactoring.html">技術的負債</a></li><li><a href="/study/design/foundations/exercises.html">第1部演習</a> を解く</li><li>第2部 SOLID を <a href="/study/design/solid/srp.html">SRP</a> から順に</li><li>第3部は全部ではなく、まず <a href="/study/design/patterns/observer.html">Observer</a> / <a href="/study/design/patterns/state.html">State</a> / <a href="/study/design/patterns/strategy.html">Strategy</a> / <a href="/study/design/patterns/command.html">Command</a> / <a href="/study/design/patterns/factory-method.html">Factory Method</a> / <a href="/study/design/patterns/singleton.html">Singleton</a> の6つ</li><li>第5部を 01 から順に(1日1〜2ページ)</li><li>第11部のケーススタディを2〜3題読み、<a href="/study/design/decisions/">判断ガイド</a>で締める</li></ol><h2 id="ルート2-unity経験者向けc-ルート" tabindex="-1">ルート2: Unity経験者向けC++ルート <a class="header-anchor" href="#ルート2-unity経験者向けc-ルート" aria-label="Permalink to &quot;ルート2: Unity経験者向けC++ルート&quot;">​</a></h2><p>「C#は書けるがC++が分からない」人向け。C#との対比を軸に進みます。</p><ol><li><a href="/study/languages/csharp/pointers-references-value-semantics.html">ポインタと参照型 / 値セマンティクス</a> — C#のclass/structとの対応から入る</li><li><a href="/study/languages/cpp/values-pointers-references.html">値型と参照・ポインタ・参照</a></li><li><a href="/study/languages/cpp/ctor-dtor-copy-move.html">コンストラクタ・デストラクタ・コピー・ムーブ</a></li><li><a href="/study/languages/cpp/raii.html">RAII</a> → <a href="/study/languages/csharp/destructor-dispose-raii-using.html">デストラクタとDispose / RAIIとusing</a></li><li><a href="/study/languages/cpp/smart-pointers.html">スマートポインタ</a> → <a href="/study/runtime/memory/ownership-and-borrowing.html">所有権と借用</a></li><li><a href="/study/languages/cpp/inheritance-and-virtual.html">継承・仮想関数</a> → <a href="/study/languages/csharp/virtual-and-polymorphism.html">仮想関数とvirtual/override</a></li><li><a href="/study/languages/cpp/templates-and-concepts.html">テンプレートとconcepts</a> → <a href="/study/languages/csharp/templates-vs-generics.html">テンプレートとジェネリック</a></li><li><a href="/study/languages/cpp/lambdas-and-functions.html">ラムダ式・関数ポインタ・std::function</a> → <a href="/study/languages/csharp/delegates-events-function-pointers.html">関数ポインタとdelegate</a></li><li><a href="/study/runtime/cpp-internals/build-pipeline-journey.html">main.cpp から CPU命令までの旅</a> → <a href="/study/runtime/cpp-internals/translation-units-and-headers.html">翻訳単位とヘッダー</a> → <a href="/study/languages/csharp/headers-vs-asmdef.html">ヘッダー分割とAssembly Definition</a></li><li><a href="/study/languages/csharp/memory-management-vs-gc.html">手動メモリ管理とGC</a> → <a href="/study/runtime/memory/gc-and-csharp-comparison.html">GCとの違い</a></li><li><a href="/study/languages/csharp/il2cpp.html">ネイティブビルドとIL2CPP</a></li><li>仕上げに <a href="/study/languages/cpp/exercises.html">第5部演習</a> と <a href="/study/languages/csharp/exercises.html">第9部演習</a></li></ol><h2 id="ルート3-設計重点ルート" tabindex="-1">ルート3: 設計重点ルート <a class="header-anchor" href="#ルート3-設計重点ルート" aria-label="Permalink to &quot;ルート3: 設計重点ルート&quot;">​</a></h2><p>「動くコードは書けるが、設計判断に自信がない」人向け。</p><ol><li>第1部を通読(<a href="/study/design/foundations/">カテゴリ目次</a>)</li><li>第2部 SOLID を通読(<a href="/study/design/solid/">カテゴリ目次</a>)— 各ページの「適用しすぎた場合の弊害」を飛ばさないこと</li><li>第3部から: <a href="/study/design/patterns/strategy.html">Strategy</a> / <a href="/study/design/patterns/state.html">State</a> / <a href="/study/design/patterns/observer.html">Observer</a> / <a href="/study/design/patterns/command.html">Command</a> / <a href="/study/design/patterns/factory-method.html">Factory Method</a> / <a href="/study/design/patterns/decorator.html">Decorator</a> / <a href="/study/design/patterns/facade.html">Facade</a> / <a href="/study/design/patterns/adapter.html">Adapter</a></li><li>第4部から: <a href="/study/game/patterns/component-and-ecs.html">Component と ECS</a> / <a href="/study/game/patterns/event-queue-and-pubsub.html">Event Queue と Pub/Sub</a> / <a href="/study/game/patterns/service-locator-and-di.html">Service Locator と DI</a> / <a href="/study/game/patterns/state-machines.html">ステートマシン</a></li><li>第11部ケーススタディを全題(<a href="/study/design/case-studies/">カテゴリ目次</a>)— 設計案の比較こそがこのルートの本体</li><li>第12部 判断ガイドを通読(<a href="/study/design/decisions/">カテゴリ目次</a>)</li><li><a href="/study/design/patterns/exercises.html">第3部演習</a> / <a href="/study/design/case-studies/exercises.html">第11部演習</a> / <a href="/study/design/decisions/exercises.html">第12部演習</a></li></ol><h2 id="ルート4-unreal-engine向けルート" tabindex="-1">ルート4: Unreal Engine向けルート <a class="header-anchor" href="#ルート4-unreal-engine向けルート" aria-label="Permalink to &quot;ルート4: Unreal Engine向けルート&quot;">​</a></h2><p>UnityからUEへ移る人、UE案件が始まる人向け。C++の土台 → UE独自仕様の順で進みます。</p><ol><li>ルート2の 1〜6 をまず終える(UEのC++は標準C++の上に載っている)</li><li><a href="/study/languages/cpp/static-inline-friend.html">static・inline・friend</a> と <a href="/study/languages/cpp/casts.html">キャスト</a></li><li><a href="/study/runtime/cpp-internals/translation-units-and-headers.html">翻訳単位とヘッダー</a> → <a href="/study/runtime/cpp-internals/symbols-and-linkage.html">シンボルとリンケージ</a>(UEのビルドエラーを読むための基礎)</li><li>第10部を順に: <a href="/study/game/unreal/uobject-actor-component.html">UObject・Actor・ActorComponent</a> → <a href="/study/game/unreal/gc-and-object-pointers.html">GCとUPROPERTY</a> → <a href="/study/game/unreal/reflection-and-uht.html">リフレクションとUHT</a> → <a href="/study/game/unreal/build-system-ubt.html">UBTとModule</a> → <a href="/study/game/unreal/smart-pointers.html">TSharedPtrなど</a> → <a href="/study/game/unreal/delegates-and-interfaces.html">DelegateとInterface</a> → <a href="/study/game/unreal/gameplay-framework.html">Gameplay Framework</a></li><li><a href="/study/game/unreal/exercises.html">第10部演習</a></li><li>ケーススタディの <a href="/study/design/case-studies/enemy-ai.html">敵AI</a> と <a href="/study/design/case-studies/screen-transition.html">画面遷移</a> をUE前提で読み直す</li></ol><h2 id="ルート5-グラフィックス志望向けルート" tabindex="-1">ルート5: グラフィックス志望向けルート <a class="header-anchor" href="#ルート5-グラフィックス志望向けルート" aria-label="Permalink to &quot;ルート5: グラフィックス志望向けルート&quot;">​</a></h2><p>描画・エンジン内部・最適化に進みたい人向け。メモリとCPUの理解を最優先します。</p><ol><li><a href="/study/languages/cpp/values-pointers-references.html">値型と参照・ポインタ・参照</a> → <a href="/study/languages/cpp/arrays-and-strings.html">配列と文字列</a> → <a href="/study/languages/cpp/stl.html">STLコンテナ</a></li><li><a href="/study/runtime/cpp-internals/memory-layout.html">メモリレイアウト・パディング・アラインメント</a></li><li><a href="/study/runtime/cpp-internals/function-calls-and-cpu.html">関数呼び出しとCPU</a> → <a href="/study/runtime/cpp-internals/cache-branch-simd.html">キャッシュ・分岐予測・SIMD</a></li><li><a href="/study/runtime/memory/cache-locality-aos-soa.html">キャッシュ局所性と AoS/SoA</a> → <a href="/study/game/patterns/optimization-patterns.html">Data Localityなど最適化系パターン</a></li><li><a href="/study/runtime/memory/allocators-and-pools.html">placement new・allocator・pool</a></li><li><a href="/study/runtime/cpp-internals/optimization-and-ub.html">コンパイラ最適化とUB</a> → <a href="/study/languages/cpp/undefined-behavior.html">未定義動作</a></li><li><a href="/study/game/patterns/object-pool.html">Object Pool</a> / <a href="/study/game/patterns/optimization-patterns.html">Double Buffer(最適化系パターン内)</a> / <a href="/study/game/patterns/command-buffer-and-input.html">Command Buffer</a></li><li><a href="/study/tools/build/build-configurations.html">ビルド構成</a> と <a href="/study/tools/build/debugging-and-analysis.html">サニタイザ</a></li><li><a href="/study/runtime/cpp-internals/exercises.html">第6部演習</a> と <a href="/study/runtime/memory/exercises.html">第7部演習</a></li></ol><h2 id="進め方のコツ" tabindex="-1">進め方のコツ <a class="header-anchor" href="#進め方のコツ" aria-label="Permalink to &quot;進め方のコツ&quot;">​</a></h2><ul><li>1ページ読んだら、そのページの「理解度チェック」に口頭で答えてみる。答えられなければ読み直すのではなく、<strong>手を動かす</strong>(演習をやる)。</li><li>パターンのページは「使わない場面」を読むまでが1ページ。</li><li>C++のページで分からない用語が出たら、その場で<a href="/study/guide/cpp-glossary.html">用語集</a>を引き、深追いは後回しにする。</li></ul><hr><p><a href="/study/guide/cpp-index.html">目次に戻る</a></p>',24)])])}const c=e(n,[["render",l]]);export{p as __pageData,c as default};
